exercises.solution:
function discographyReport(artists, albums) {
  return artists.map(artist => {
    const artistAlbums = albums.filter(a => a.artistId === artist.id);
    const totalTracks = artistAlbums.reduce((sum, a) => sum + a.tracks.length, 0);
    const totalSales = artistAlbums.reduce((sum, a) => sum + a.certification.sales, 0);
    const topAlbum = artistAlbums.reduce((best, a) => a.ratings.fan > best.ratings.fan ? a : best);
    return {
      name: artist.name,
      albumCount: artistAlbums.length,
      totalTracks,
      totalSales,
      topAlbum: topAlbum.title
    };
  }).sort((a, b) => b.totalSales - a.totalSales);
}

