function streamingAnalysis(artists, albums) {
  const totalTracks = albums.reduce((sum, a) => sum + a.tracks.length, 0);
  const avgListeners = Math.round(artists.reduce((sum, a) => sum + a.monthlyListeners, 0) / artists.length);
  const mostGrammys = artists.reduce((best, a) => a.grammyWins > best.grammyWins ? a : best);
  const highestRatedAlbum = albums.reduce((best, a) => a.ratings.fan > best.ratings.fan ? a : best);
  const hrArtist = artists.find(a => a.id === highestRatedAlbum.artistId);
  const certificationCounts = albums.reduce((counts, a) => {
    counts[a.certification.status] = (counts[a.certification.status] || 0) + 1;
    return counts;
  }, {});
  return {
    totalArtists: artists.length,
    totalAlbums: albums.length,
    totalTracks,
    avgListeners,
    mostGrammys: { name: mostGrammys.name, wins: mostGrammys.grammyWins },
    highestRated: { title: highestRatedAlbum.title, artist: hrArtist.name, fan: highestRatedAlbum.ratings.fan },
    certificationCounts
  };
}

