/**
 * @param {Object[]} platforms - Array of platform objects
 * @param {Object[]} games - Array of game objects
 * @param {string} title - Title of the game
 * @returns {string[]} Platform names the game is available on
 */
function getGamePlatforms(platforms, games, title) {

}

exercises.solution:
function getGamePlatforms(platforms, games, title) {
  const game = games.find(g => g.title === title);
  if (!game) return [];
  return platforms.filter(p => game.platformIds.includes(p.id)).map(p => p.name);
}

