}

exercises.solution:
function getTotalAwards(games) {
  return games.map(g => ({
    title: g.title,
    totalAwards: g.awards.gameAwards + g.awards.bafta + g.awards.diceAwards
  })).sort((a, b) => b.totalAwards - a.totalAwards);
}

