/**
 * @param {Object[]} platforms - Array of platform objects
 * @param {Object[]} games - Array of game objects
 * @param {string} platformName - Name of the platform
 * @returns {string[]} Titles exclusive to that platform
 */
function getExclusives(platforms, games, platformName) {

}

exercises.solution:
function getExclusives(platforms, games, platformName) {
  const platform = platforms.find(p => p.name === platformName);
  if (!platform) return [];
  return games.filter(g => g.platformIds.length === 1 && g.platformIds[0] === platform.id).map(g => g.title);
}

