/**
 * @param {Object[]} games - Array of game objects
 * @returns {Object[]} Array of { title, completionist } sorted descending
 */
function sortByPlaytime(games) {

}

exercises.solution:
function sortByPlaytime(games) {
  return games
    .filter(g => g.playtime.completionist !== null)
    .map(g => ({ title: g.title, completionist: g.playtime.completionist }))
    .sort((a, b) => b.completionist - a.completionist);
}

