/**
 * @param {Object[]} games - Array of game objects
 * @param {string} genre - Genre to calculate average for
 * @returns {number} Average Metacritic score rounded to 1 decimal
 */
function avgMetacriticByGenre(games, genre) {

}

exercises.solution:
function avgMetacriticByGenre(games, genre) {
  const matching = games.filter(g => g.genres.includes(genre));
  if (matching.length === 0) return 0;
  const sum = matching.reduce((total, g) => total + g.ratings.metacritic, 0);
  return Math.round((sum / matching.length) * 10) / 10;
}

