exercises.solution:
function platformReport(platforms, games) {
  return platforms.map(p => {
    const pGames = games.filter(g => g.platformIds.includes(p.id));
    const totalPlayers = pGames.reduce((sum, g) => sum + g.players.total, 0);
    const topGame = pGames.reduce((best, g) => g.ratings.metacritic > best.ratings.metacritic ? g : best);
    const exclusiveCount = pGames.filter(g => g.platformIds.length === 1).length;
    return {
      name: p.name,
      gameCount: pGames.length,
      totalPlayers,
      topGame: topGame.title,
      exclusiveCount
    };
  }).sort((a, b) => b.gameCount - a.gameCount);
}

