exercises.solution:
function gamingAnalysis(platforms, games) {
  const totalPlayers = games.reduce((sum, g) => sum + g.players.total, 0);
  const avgMetacritic = Math.round((games.reduce((sum, g) => sum + g.ratings.metacritic, 0) / games.length) * 10) / 10;
  const mostAwarded = games.map(g => ({ title: g.title, totalAwards: g.awards.gameAwards + g.awards.bafta + g.awards.diceAwards })).reduce((best, g) => g.totalAwards > best.totalAwards ? g : best);
  const mostPopular = games.reduce((best, g) => g.players.total > best.players.total ? g : best);
  const manufacturerBreakdown = {};
  platforms.forEach(p => {
    if (!manufacturerBreakdown[p.manufacturer]) {
      manufacturerBreakdown[p.manufacturer] = { platforms: [], totalGamesSold: 0 };
    }
    manufacturerBreakdown[p.manufacturer].platforms.push(p.name);
    if (p.unitsSold !== null) {
      manufacturerBreakdown[p.manufacturer].totalGamesSold += p.unitsSold;
    }
  });
  return {
    totalGames: games.length,
    totalPlatforms: platforms.length,
    totalPlayers,
    avgMetacritic,
    mostAwarded,
    mostPopular: { title: mostPopular.title, players: mostPopular.players.total },
    manufacturerBreakdown
  };
}

